import { useEffect, useState, type FormEvent } from 'react';
import type { MemberProfile } from '../../lib/session';
import {
  fetchThreadPage,
  pageCount,
  sanitizeSearch,
  type ThreadSummary,
} from '../../lib/threads';
import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

interface MessagesProps {
  profile: MemberProfile;
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date;
  /**
   * Cableada por el shell desde `App.tsx` para un MSG-02 que aún no existe
   * (F-118). Recibida e ignorada: abrir un hilo no lleva a ninguna parte en el
   * MVP, así que esta prop no se usa.
   */
  onOpenThread?: (threadId: string) => void;
}

const countFormat = new Intl.NumberFormat('es-ES', { useGrouping: false });

/**
 * Pantalla MSG-01 · Lista de Hilos.
 *
 * Es LA PANTALLA, no un componente de presentación: posee el estado de
 * búsqueda y de página y llama a `fetchThreadPage` con `profile.orgId`.
 */
export function Messages({ profile, now = new Date() }: MessagesProps) {
  const [searchInput, setSearchInput] = useState('');
  const [query, setQuery] = useState('');
  const [page, setPage] = useState(1);
  const [threads, setThreads] = useState<ThreadSummary[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);

    fetchThreadPage({ orgId: profile.orgId, search: query, page })
      .then((res) => {
        if (cancelled) return;
        setThreads(res.threads);
        setTotal(res.total);
      })
      .catch(() => {
        if (cancelled) return;
        setError('No se pudieron cargar los hilos. Inténtalo de nuevo.');
        setThreads([]);
        setTotal(0);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [profile.orgId, query, page]);

  function handleSearch(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setPage(1);
    setQuery(sanitizeSearch(searchInput));
  }

  const pages = pageCount(total);

  return (
    <div className={styles.page}>
      <p className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</p>
      <h1 className={styles.pageTitle}>Hilos</h1>
      <p className={styles.pageSub}>
        Tus conversaciones con otros distribuidores. Todo el contenido está
        cifrado de extremo a extremo.
      </p>

      <div className={styles.actionsBar}>
        <form className={styles.searchWrap} role="search" onSubmit={handleSearch}>
          <i className="ti ti-search" aria-hidden="true" />
          <input
            className={styles.searchInput}
            type="search"
            value={searchInput}
            onChange={(e) => setSearchInput(e.target.value)}
            placeholder="Buscar por nombre de organización..."
            aria-label="Buscar por nombre de organización"
          />
        </form>
        {/* DIR-01 no está entre las 8 pantallas del MVP: el control existe pero
            no lleva a ninguna parte, así que se pinta deshabilitado con el
            motivo visible (F-023). */}
        <button
          type="button"
          className={styles.btnPrimary}
          disabled
          aria-describedby="nuevo-contacto-motivo"
        >
          <i className="ti ti-address-book" aria-hidden="true" />
          Nuevo contacto
        </button>
        <span className={styles.btnHint} id="nuevo-contacto-motivo">
          El Directorio de Organizaciones (DIR-01) está fuera del MVP y estará
          disponible en una próxima versión.
        </span>
        {total > 0 && (
          <span className={styles.threadCount}>
            {countFormat.format(total)}{' '}
            {total === 1 ? 'hilo' : 'hilos'} · Página {page} de {pages}
          </span>
        )}
      </div>

      {error ? (
        <div className={styles.error} role="alert">
          {error}
        </div>
      ) : loading ? (
        <div className={styles.status} role="status">
          Cargando hilos…
        </div>
      ) : threads.length === 0 && query ? (
        <div className={styles.empty}>
          <p>No se encontraron hilos para «{query}».</p>
        </div>
      ) : (
        <>
          {/* MSG-02 no existe: onOpen es un no-op a propósito. */}
          <ThreadList threads={threads} now={now} onOpen={() => {}} />
          {pages > 1 && (
            <div className={styles.pagination}>
              <button
                type="button"
                className={styles.pageBtn}
                disabled={page === 1}
                onClick={() => setPage((p) => Math.max(1, p - 1))}
                aria-label="Página anterior"
              >
                ‹
              </button>
              {Array.from({ length: pages }, (_, i) => i + 1).map((p) => (
                <button
                  key={p}
                  type="button"
                  className={`${styles.pageBtn} ${p === page ? styles.pageActive : ''}`}
                  aria-current={p === page ? 'page' : undefined}
                  onClick={() => setPage(p)}
                >
                  {p}
                </button>
              ))}
              <button
                type="button"
                className={styles.pageBtn}
                disabled={page >= pages}
                onClick={() => setPage((p) => Math.min(pages, p + 1))}
                aria-label="Página siguiente"
              >
                ›
              </button>
            </div>
          )}
        </>
      )}
    </div>
  );
}

