import {
  previewLabel,
  relativeTime,
  stateTone,
  type ThreadSummary,
} from '../../lib/threads';
import styles from './ThreadList.module.css';

interface ThreadListProps {
  threads: ThreadSummary[];
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date;
  onOpen: (id: string) => void;
}

/**
 * Lista de hilos de MSG-01, presentacional.
 *
 * Pinta las filas en el orden exacto en que las recibe: el orden lo decide el
 * servidor (`fetchThreadPage` ordena por `last_item_at` descendente). Al abrir
 * una fila avisa con el ID del hilo, no con el objeto. Si no hay hilos, pinta
 * el estado vacío de la spec §6.
 */
export function ThreadList({ threads, now = new Date(), onOpen }: ThreadListProps) {
  if (threads.length === 0) {
    return (
      <div className={styles.empty}>
        <p>
          Todavía no tienes ninguna conversación. Usa el Directorio para
          contactar con otras organizaciones.
        </p>
        {/* DIR-01 no está entre las 8 pantallas del MVP: el control existe pero
            no lleva a ninguna parte, así que se pinta deshabilitado con el
            motivo visible (F-023). */}
        <span className={styles.btnWrap}>
          <button
            type="button"
            className={styles.primaryBtn}
            disabled
            aria-describedby="thread-empty-directorio-motivo"
          >
            <i className="ti ti-address-book" aria-hidden="true" />
            Ir al Directorio
          </button>
          <span className={styles.btnHint} id="thread-empty-directorio-motivo">
            El Directorio de Organizaciones (DIR-01) está fuera del MVP y estará
            disponible en una próxima versión.
          </span>
        </span>
      </div>
    );
  }

  return (
    <ul className={styles.list}>
      {threads.map((thread) => {
        const tone = stateTone(thread.state);
        return (
          <li key={thread.id} className={styles.rowItem}>
            <button
              type="button"
              className={styles.row}
              onClick={() => onOpen(thread.id)}
              aria-label={`Abrir hilo con ${thread.counterpartyName}`}
            >
              <div className={styles.top}>
                <span className={styles.org}>{thread.counterpartyName}</span>
                <span className={styles.countryBadge}>
                  {thread.counterpartyCountry}
                </span>
              </div>
              <div className={styles.tsRow}>
                <time className={styles.ts} dateTime={thread.lastItemAt}>
                  {relativeTime(thread.lastItemAt, now)}
                </time>
              </div>
              <div className={styles.bottom}>
                <span className={styles.preview}>{previewLabel(thread.lastItem)}</span>
                <span className={`${styles.stateBadge} ${styles[tone]}`}>
                  {thread.state}
                </span>
              </div>
            </button>
          </li>
        );
      })}
    </ul>
  );
}
